pub async fn load_image_texture(
    url: String,
    file_hash: String,
    ctx: ContentProviderContext,
) -> Result<Option<Variant>, anyhow::Error> {
    let absolute_file_path = format!("{}{}", ctx.content_folder, file_hash);
    let bytes_vec = ctx
        .resource_provider
        .fetch_resource_with_data(&url, &file_hash, &absolute_file_path)
        .await
        .map_err(anyhow::Error::msg)?;

    if bytes_vec.is_empty() {
        return Err(anyhow::Error::msg("Empty texture data"));
    }

    let _thread_safe_check = GodotSingleThreadSafety::acquire_owned(&ctx)
        .await
        .ok_or(anyhow::Error::msg("Failed trying to get thread-safe check"))?;

    // Check for formats that need special handling
    // AVIF: Not supported - use fallback texture (no pure Rust decoder available yet)
    if infer_mime::is_avif(&bytes_vec) {
        tracing::warn!("Unsupported image format: AVIF ({}), using fallback", url);
        DirAccess::remove_absolute(&GString::from(&absolute_file_path));
        return Ok(Some(create_fallback_texture_entry().to_variant()));
    }

    // HEIC: Not supported - use fallback texture
    if infer_mime::is_heic(&bytes_vec) {
        tracing::warn!("Unsupported image format: HEIC ({}), using fallback", url);
        DirAccess::remove_absolute(&GString::from(&absolute_file_path));
        return Ok(Some(create_fallback_texture_entry().to_variant()));
    }
    // GIF: Decode and create AnimatedTexture with compressed frames
    if infer_mime::is_gif(&bytes_vec) {
        tracing::debug!("Decoding GIF animation using Rust image crate: {}", url);
        let max_size = ctx.texture_quality.to_max_size();

        let (mut texture, original_size, image) =
            match decode_gif_to_animated_texture(&bytes_vec, max_size) {
                Ok(result) => result,
                Err(e) => {
                    tracing::warn!("Failed to decode GIF ({}): {}, using fallback", url, e);
                    DirAccess::remove_absolute(&GString::from(&absolute_file_path));
                    return Ok(Some(create_fallback_texture_entry().to_variant()));
                }
            };

        texture.set_name(&GString::from(&url));

        let texture_entry = Gd::from_init_fn(|_base| TextureEntry {
            image,
            texture,
            original_size,
            failed: false,
        });

        return Ok(Some(texture_entry.to_variant()));
    }

    // Animated WebP: Decode using Rust image crate (Godot only supports static WebP)
    if infer_mime::is_animated_webp(&bytes_vec) {
        tracing::debug!("Decoding animated WebP using Rust image crate: {}", url);
        let max_size = ctx.texture_quality.to_max_size();

        let (mut texture, original_size, image) =
            match decode_animated_webp_to_texture(&bytes_vec, max_size) {
                Ok(result) => result,
                Err(e) => {
                    tracing::warn!(
                        "Failed to decode animated WebP ({}): {}, using fallback",
                        url,
                        e
                    );
                    DirAccess::remove_absolute(&GString::from(&absolute_file_path));
                    return Ok(Some(create_fallback_texture_entry().to_variant()));
                }
            };

        texture.set_name(&GString::from(&url));

        let texture_entry = Gd::from_init_fn(|_base| TextureEntry {
            image,
            texture,
            original_size,
            failed: false,
        });

        return Ok(Some(texture_entry.to_variant()));
    }

    let bytes = PackedByteArray::from_vec(&bytes_vec);

    let mut image = Image::new_gd();
    // Static WebP is handled by Godot's native loader below
    let err = if infer_mime::is_png(&bytes_vec) {
        image.load_png_from_buffer(&bytes)
    } else if infer_mime::is_jpeg(&bytes_vec) || infer_mime::is_jpeg2000(&bytes_vec) {
        image.load_jpg_from_buffer(&bytes)
    } else if infer_mime::is_webp(&bytes_vec) {
        image.load_webp_from_buffer(&bytes)
    } else if infer_mime::is_tga(&bytes_vec) {
        image.load_tga_from_buffer(&bytes)
    } else if infer_mime::is_ktx(&bytes_vec) {
        image.load_ktx_from_buffer(&bytes)
    } else if infer_mime::is_bmp(&bytes_vec) {
        image.load_bmp_from_buffer(&bytes)
    } else if infer_mime::is_svg(&bytes_vec) {
        image.load_svg_from_buffer(&bytes)
    } else {
        // Unknown format - use fallback texture
        let format_hint = if bytes_vec.len() >= 4 {
            format!(
                "magic bytes: {:02x} {:02x} {:02x} {:02x}",
                bytes_vec[0], bytes_vec[1], bytes_vec[2], bytes_vec[3]
            )
        } else {
            "insufficient data".to_string()
        };
        tracing::warn!(
            "Unknown/unsupported image format ({}) for {}, using fallback",
            format_hint,
            url
        );
        DirAccess::remove_absolute(&GString::from(&absolute_file_path));
        return Ok(Some(create_fallback_texture_entry().to_variant()));
    };

    if err != Error::OK {
        let err_code = err.to_variant().to::<i32>();
        tracing::warn!(
            "Error loading texture {}: error code {}, using fallback",
            absolute_file_path,
            err_code
        );
        DirAccess::remove_absolute(&GString::from(&absolute_file_path));
        return Ok(Some(create_fallback_texture_entry().to_variant()));
    }

    let original_size = image.get_size();

    let max_size = ctx.texture_quality.to_max_size();
    let mut texture: Gd<Texture2D> = if std::env::consts::OS == "ios"
        || std::env::consts::OS == "android"
    {
        create_compressed_texture(&mut image, max_size)
    } else {
        resize_image(&mut image, max_size);
        let texture = ImageTexture::create_from_image(&image.clone()).ok_or(anyhow::Error::msg(
            format!("Error creating texture from image {}", absolute_file_path),
        ))?;
        texture.upcast()
    };

    texture.set_name(&GString::from(&url));

    let texture_entry = Gd::from_init_fn(|_base| TextureEntry {
        image,
        texture,
        original_size,
        failed: false,
    });

    Ok(Some(texture_entry.to_variant()))
}

/// Pads image dimensions to multiples of 4 for ETC2 compression compatibility.
/// ETC2 operates on 4x4 pixel blocks and requires dimensions divisible by 4.
fn pad_image_to_multiple_of_4(image: &mut Gd<Image>) -> bool {
    let w = image.get_width();
    let h = image.get_height();
    let pw = ((w + 3) / 4) * 4;
    let ph = ((h + 3) / 4) * 4;
    if w != pw || h != ph {
        image.resize(pw, ph);
        true
    } else {
        false
    }
}

/// Creates a texture from a compressed image, resizing if needed.
/// Uses ETC2 compression for better memory usage on mobile platforms.
///
/// The ETC2 image is wrapped in a `PortableCompressedTexture2D` with
/// `set_keep_compressed_buffer(true)`. PCT2 ships its compressed CPU
/// buffer verbatim through `save_node_as_scene`, bypassing the GPU
/// readback that `ImageTexture::create_from_image` triggers on the
/// asset-server's llvmpipe stack — that readback corrupts the ETC2
/// bytes, so every mesh material baked into the optimized `.scn`
/// shipped from prod renders as per-allocation noise on device (every
/// mesh surface looks like static). PCT2 round-trips cleanly under
/// `--rendering-driver opengl3` once the DCL Godot fork's PCT2
/// serialization fix is in (PR decentraland/godotengine#14, merged
/// 2026-06-03 as `4.6.2.stable.gh.9ee6af7ab`). Older fork binaries
/// (`stable.gh.7e5bfa428` and earlier) ship PCT2 with no compressed
/// buffer and would render magenta on device — confirm the container's
/// `decentraland.godot.client.x86_64 --version` is `gh.9ee6af7ab` or
/// newer before deploying.
///
/// Falls back to uncompressed texture if compression fails.
pub fn create_compressed_texture(image: &mut Gd<Image>, max_size: i32) -> Gd<Texture2D> {
    assert_pct2_serialization_ok();
    resize_image(image, max_size);

    if !image.is_compressed() {
        pad_image_to_multiple_of_4(image);

        let result = image.compress(CompressMode::ETC2);
        if result != Error::OK {
            tracing::warn!(
                "ETC2 compression failed ({}x{}, error {:?}), using uncompressed texture",
                image.get_width(),
                image.get_height(),
                result
            );
        }
    }

    let mut pct2 = PortableCompressedTexture2D::new_gd();
    pct2.set_keep_compressed_buffer(true);
    pct2.create_from_image(
        &*image,
        portable_compressed_texture_2d::CompressionMode::ETC2,
    );
    if pct2.get_width() == 0 || pct2.get_height() == 0 {
        tracing::error!(
            "Failed to create PCT2 from image ({}x{}), using placeholder",
            image.get_width(),
            image.get_height()
        );
        return create_placeholder_texture();
    }
    pct2.upcast()
}

/// Hard cap on any single dimension, regardless of pixel budget.
/// Keeps us safely under common GPU `MAX_TEXTURE_SIZE` limits on mobile / Quest.
const MAX_TEXTURE_DIMENSION: i32 = 4096;

/// Downscale `image` (preserving aspect ratio) so that:
///   - total pixels <= `max_size * max_size`, AND
///   - neither dimension exceeds `MAX_TEXTURE_DIMENSION`.
///
/// Returns true if the image was resized.
pub fn resize_image(image: &mut Gd<Image>, max_size: i32) -> bool {
    let w = image.get_width();
    let h = image.get_height();
    if w <= 0 || h <= 0 || max_size <= 0 {
        return false;
    }

    let max_pixels = (max_size as i64) * (max_size as i64);
    let cur_pixels = (w as i64) * (h as i64);

    let over_pixel_budget = cur_pixels > max_pixels;
    let over_dim_cap = w > MAX_TEXTURE_DIMENSION || h > MAX_TEXTURE_DIMENSION;
    if !over_pixel_budget && !over_dim_cap {
        return false;
    }

    let scale_pixels = if over_pixel_budget {
        (max_pixels as f64 / cur_pixels as f64).sqrt()
    } else {
        1.0
    };
    let scale_dim = (MAX_TEXTURE_DIMENSION as f64 / w as f64)
        .min(MAX_TEXTURE_DIMENSION as f64 / h as f64)
        .min(1.0);
    let scale = scale_pixels.min(scale_dim);

    // floor to guarantee new_w * new_h <= max_pixels and new dims <= cap
    let new_w = ((w as f64 * scale).floor() as i32).max(1);
    let new_h = ((h as f64 * scale).floor() as i32).max(1);

    image.resize(new_w, new_h);
    tracing::debug!("Resize! {}x{} to {}x{}", w, h, new_w, new_h);
    true
}

/// First-call self-test for the PCT2 serialization path used by
/// `create_compressed_texture`. The DCL Godot fork's
/// `PortableCompressedTexture2D` is broken on binaries older than
/// `4.6.2.stable.gh.9ee6af7ab` (PR decentraland/godotengine#14, merged
/// 2026-06-03) — `_set_data` is a no-op there, so a saved `.scn`'s PCT2
/// reload returns `null` from `get_image()` and every mesh material
/// renders magenta on device. Without this assertion, an asset-server
/// image regression silently bakes thousands of broken `.scn` files.
///
/// The self-test packs a tiny ETC2-compressed PCT2 to a `.res` on disk,
/// reloads it, and checks `get_image()` returns the expected dimensions.
/// `panic!` on failure — every baked asset would be broken anyway, so
/// failing fast at startup is strictly better than shipping the bake.
fn assert_pct2_serialization_ok() {
    static ONCE: Once = Once::new();
    ONCE.call_once(|| {
        // 4x4 RGBA8 (ETC2's block size) — smallest valid input
        let pixels = PackedByteArray::from_vec(&[255u8; 4 * 4 * 4]);
        let Some(mut img) = Image::create_from_data(4, 4, false, GodotFormat::RGBA8, &pixels)
        else {
            tracing::error!("[pct2-selfcheck] failed to build probe image; skipping");
            return;
        };
        if img.compress(CompressMode::ETC2) != Error::OK {
            tracing::error!("[pct2-selfcheck] ETC2 compress failed on probe image; skipping");
            return;
        }
        let mut pct2 = PortableCompressedTexture2D::new_gd();
        pct2.set_keep_compressed_buffer(true);
        pct2.create_from_image(&img, portable_compressed_texture_2d::CompressionMode::ETC2);
        let probe_path = "user://_pct2_selfcheck.res";
        let save_err = ResourceSaver::singleton()
            .save_ex(&pct2.clone().upcast::<Resource>())
            .path(probe_path)
            .done();
        if save_err != Error::OK {
            tracing::error!(
                "[pct2-selfcheck] ResourceSaver.save failed ({:?}); skipping",
                save_err
            );
            return;
        }
        let reloaded = ResourceLoader::singleton()
            .load(probe_path)
            .and_then(|r| r.try_cast::<PortableCompressedTexture2D>().ok());
        let _ = DirAccess::remove_absolute(probe_path);
        let Some(reloaded) = reloaded else {
            panic!(
                "[pct2-selfcheck] PCT2 reload returned null — fork binary missing \
                 the PortableCompressedTexture2D serialization fix (PR \
                 decentraland/godotengine#14). Upgrade the asset-server's Godot \
                 binary to 4.6.2.stable.gh.9ee6af7ab or newer."
            );
        };
        if reloaded.get_image().is_none() || reloaded.get_width() != 4 || reloaded.get_height() != 4
        {
            panic!(
                "[pct2-selfcheck] PCT2.get_image() returned null after reload — \
                 fork binary is missing the PortableCompressedTexture2D \
                 serialization fix (PR decentraland/godotengine#14). Upgrade \
                 the asset-server's Godot binary to 4.6.2.stable.gh.9ee6af7ab \
                 or newer."
            );
        }
        tracing::info!("[pct2-selfcheck] PortableCompressedTexture2D round-trip OK");
    });
}

