    pub fn destinations_api() -> GString {
        urls::destinations_api().to_godot()
    }
    #[func]
    pub fn events_api() -> GString {
        urls::events_api().to_godot()
    }
    #[func]
    pub fn mobile_events_api() -> GString {
        urls::mobile_events_api().to_godot()
    }
    #[func]
    pub fn notifications_api() -> GString {
        urls::notifications_api().to_godot()
    }
    #[func]
    pub fn mobile_bff() -> GString {
        urls::mobile_bff().to_godot()
    }
    #[func]
    pub fn attestation_bff() -> GString {
        urls::attestation_bff().to_godot()
    }

    // Frontend
    #[func]
    pub fn host() -> GString {
        urls::host().to_godot()
    }
    #[func]
    pub fn marketplace() -> GString {
        urls::marketplace().to_godot()
    }
    #[func]
    pub fn marketplace_catalog_api() -> GString {
        urls::marketplace_catalog_api().to_godot()
    }
    #[func]
    pub fn marketplace_claim_name() -> GString {
        urls::marketplace_claim_name().to_godot()
    }
    #[func]
